    apply: { situation: ['Ren welcomes Emma to the Osaka office. Read their conversation.', 'レンが大阪のオフィスでエマを迎えます。会話を読みましょう。'], roles: ['Ren', 'Emma'], dialogue: [['Ren', 'Hi, you must be Emma. I\'m Ren. Welcome to the team.'], ['Emma', 'Thank you. I\'ve just joined as a graphic designer.'], ['Ren', 'What kind of design do you enjoy?'], ['Emma', 'Posters and page layouts. I\'m excited, but a little nervous.'], ['Ren', 'That\'s normal. Let me show you around.'], ['Emma', 'Thanks. Where do we have team meetings?'], ['Ren', 'In the room by the window. Are you based in Osaka?'], ['Emma', 'I live in Kyoto. I\'ll be here on Mondays and Fridays.'], ['Ren', 'If you need anything, just ask me.'], ['Emma', 'I will. I\'m looking forward to working with you.']], questions: [['What kind of work does Emma enjoy?', 'Posters and page layouts.'], ['Which days does she work in the Osaka office?', 'Mondays and Fridays.'], ['What does Ren offer?', 'To show her around and help her.']] },
