export const chapter5Id = (number: StoryLessonNumber) => `conversational-skills-L3-C5-${number}-${chapter5Episodes[number].skill}-ja-v1`;

const pronunciationSets = [
  { sounds: ['/b/', '/p/'], pairs: [['big', '大きい', 'pig', '豚'], ['bear', '熊', 'pear', '洋梨'], ['back', '背中', 'pack', '荷造りする']], tips: ['Close both lips, then release with your voice for /b/.', 'Close both lips, then release a short puff of air without your voice for /p/.'] },
  { sounds: ['/l/', '/r/'], pairs: [['light', '光', 'right', '右'], ['led', '導いた', 'red', '赤い'], ['lock', '鍵をかける', 'rock', '岩']], tips: ['For /l/, touch the tongue tip to the ridge behind the upper front teeth.', 'For /r/, the tongue tip does not touch that ridge. Model your natural accent.'] },
  { sounds: ['/m/', '/n/'], pairs: [['map', '地図', 'nap', '昼寝'], ['met', '会った', 'net', '網'], ['mice', 'ネズミ（複数形）', 'nice', 'すてきな']], tips: ['For /m/, keep the lips together and let the sound come through the nose.', 'For /n/, touch the tongue tip to the ridge behind the upper front teeth.'] },
  { sounds: ['/t/', '/d/'], pairs: [['two', '二つ', 'do', 'する'], ['ten', '十', 'den', '動物のすみか'], ['town', '町', 'down', '下へ']], tips: ['For /t/, release the tongue tip from the ridge behind the upper teeth without your voice.', 'For /d/, use the same tongue position and add your voice.'] },
];

export function buildTwoCitiesLesson(number: StoryLessonNumber, previous: any = {}, reference?: any) {
  const index = storyLessonNumbers.indexOf(number);
  const lesson = buildNewBeginningLesson(number, previous, 'https://api.fluentxverse.com', reference, {
    episode: chapter5Episodes[number], id: chapter5Id(number), chapterName: 'Two Cities, One Secret',
    setting: 'Kamo House and Kyoto, with a fictional design agency and nearby lunch places in Osaka.',
    previousSummary: index === 0 ? 'The Osaka agency is considering Emma\'s request for two office days and three days working from Kyoto. She and Leo are waiting for the final answer.' : chapter5Episodes[requireDefined(storyLessonNumbers[index - 1], "storyLessonNumbers[index - 1]")].closing,
    storyNotes: 'Adapted from the supplied eight-episode Chapter 5 outline. Slots1-4/6-9;5/10 remain dynamic checkpoints. Same speaking/listening/reading/speaking then speaking/speaking/reading/speaking pattern. Agency approves hybrid Monday morning before Chapter4 deadline; Emma accepts and starts following month with Monday/Friday office and three Kyoto workdays. Lesson6 extra Thursday office/gathering is separate from Lesson7 Friday private dinner. Replace original physical-intimacy incident entirely with a hidden private dinner and false work message; do not add physical intimacy. Lesson7 boundary call is to Ren, not a disclosure to Leo. Lesson8 Saturday advice, Sunday6 cafe plan, Monday10 office handover. Lesson9 Ren message reveals dinner, Emma admits truth, Leo asks for time. Relationship outcome remains unresolved. Short supported B1 language, Japanese, direct roles, tutor-first dialogue and fixed guides/rubric; no mandatory monologue, optional-character disclaimers or new images. Evaluate observed language and comprehension, not a required emotional performance or forgiveness.',
  });
  const pronunciation = requireDefined(pronunciationSets[index % pronunciationSets.length], "pronunciationSets[index % pronunciationSets.length]");
  lesson.learnData.steps[0].pronunciationPart = {
    instruction: 'III. Listen and repeat. Practise the difference between the sounds.',
    instructionTranslation: '聞いて繰り返しましょう。二つの音の違いを練習しましょう。',
    leftColumn: { soundSymbol: pronunciation.sounds[0], images: [], words: pronunciation.pairs.map((pair, i) => ({ word: pair[0], translation: pair[1], isHighlighted: i === 0 })) },
    rightColumn: { soundSymbol: pronunciation.sounds[1], images: [], words: pronunciation.pairs.map((pair, i) => ({ word: pair[2], translation: pair[3], isHighlighted: i === 0 })) },
    tutorSteps: [
      { instruction: 'Introduce Part III and read the instructions.', script: `Now let's practise ${pronunciation.sounds.join(' and ')}. Listen and repeat.` },
      { instruction: `Model ${pronunciation.sounds[0]}, then read each word on the left and have the student repeat.`, tip: pronunciation.tips[0] },
      { instruction: `Model ${pronunciation.sounds[1]}, then read each word on the right and have the student repeat.`, tip: pronunciation.tips[1] },
      { instruction: 'Read each pair and have the student repeat.', script: `Now let's compare the words. ${pronunciation.pairs.map(pair => `${pair[0]}, ${pair[2]}.`).join(' ')}`, tip: 'Repeat a difficult pair once if needed. Keep this part to about one minute.' },
      { instruction: 'Transition to Step B.', script: `Great! Let's go to Step B ${lesson.skill === 'reading' ? 'Reading' : 'Grammar'} Tip!` },
    ],
  };
  lesson.storyData.characters = [
    { id: 'emma', name: 'Emma', role: 'main', description: 'Graphic designer living in Kyoto and working a hybrid Osaka role. She hides a private dinner with Ren, then must take responsibility with Leo.' },
    { id: 'leo', name: 'Leo', role: 'supporting', description: 'Baker and Emma\'s partner in Kyoto. He supports her career, feels let down by missed plans, and needs time after learning she was not honest.' },
    { id: 'ren', name: 'Ren', role: 'supporting', description: 'Senior designer who welcomes Emma, shares her interests, and develops feelings for her. Their project handover remains a professional task.' },
    { id: 'claire', name: 'Claire', role: 'supporting', description: 'Kamo House cafe organizer who notices Leo\'s disappointment and listens to him.' },
    { id: 'nao', name: 'Nao', role: 'supporting', description: 'Ceramic artist and Emma\'s friend. Advises honest explanation, responsibility and room for Leo to respond.' },
  ];
  return { course: 'conversational-skills', level: 3, chapter: 5, lessonNumber: number, levelBadge: 'BEGINNER', chapterLabel: 'Chapter 5: Two Cities, One Secret', status: previous?.status || 'draft', overlayColor: '#17252bcc', supportLanguage: 'ja', ...lesson };
}
export function buildTwoCitiesChapter(reference?: any) {
  return storyLessonNumbers.map(number => buildTwoCitiesLesson(number, {}, reference));
}
